/** One plain argument: an element stays an element, a list and a number go through Intl. */
function argument(value: unknown, intl: I18n.IntlKit): I18n.Part {
  if (Array.isArray(value)) {
    return { kind: "text", text: intl.list().format(value as readonly string[]) };
  }

  if (typeof value === "number") return { kind: "text", text: intl.number().format(value) };

  if (
    typeof value === "object" &&
    value !== null &&
    "type" in value &&
    "props" in value &&
    "children" in value
  ) {
    return { kind: "element", node: value as I18n.ElementNode };
  }

  return { kind: "text", text: String(value) };
}

/** Milliseconds as Intl.DurationFormat reads them: whole seconds rounded up, seconds always. */
function duration(ms: number): Partial<Record<Intl.DurationFormatUnit, number>> {
  const total = Number.isFinite(ms) ? Math.max(0, Math.ceil(ms / 1000)) : 0;
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  const input: Partial<Record<Intl.DurationFormatUnit, number>> = {};

  if (hours > 0) input.hours = hours;
  if (minutes > 0) input.minutes = minutes;
  input.seconds = total % 60;

  return input;
}

